import PetObject from './data/petsData';

function PetList() {
    return (
        <ul className="pet-list">
            <li className="pet">
                <img src={PetObject.dog.image} alt={petObject.dog.name}></img>
                <h4>{PetObject.dog.name}</h4>
            </li>
            <li className="pet"></li>
        </ul>
    )
}

export default PetList
